#include "KS/SRC/ks/FEMenu_shared.h"

class PanelQuad {
public:
    virtual ~PanelQuad();
    virtual void Init(float, float, float, float, float, float, float, float,
                      float, float, float, float, float, void *);
    virtual void TurnOn(bool);
    virtual void SetLayer(int);
    virtual void Rotate(float);
    virtual void Rotate(float, float, float);
    virtual void Update(float);
    virtual void Draw(int layer = 0, float alpha = -1.0f);
};

class TextString {
public:
    virtual ~TextString();
    virtual void Update(float);
    virtual void Draw();
};

class MCDetectFrontEnd : public FEMultiMenu {
public:
    bool drawMenu();
};

struct FEManager {
    char padding[0x1567c];
    bool fe_done_loading;
};

extern FEManager frontendmanager;

class TitleFrontEnd : public FEGraphicalMenu {
    PanelQuad *bkg, *box[9];
    TextString *loading;
    int loading_draw_counter;
    MCDetectFrontEnd *mc;

public:
    void Draw();
};

__asm__(".equ frontendmanager, 0x003E7728");
__asm__(".equ drawMenu__16MCDetectFrontEnd, 0x001A4260");

void TitleFrontEnd::Draw()
{
    bkg->Draw(0);
    if (active)
    {
        if (active != mc || mc->drawMenu()) 
        {
            for(int i=0; i<9; i++)
                box[i]->Draw(0);
        }
        active->Draw();
    }
    else
    {
        if(loading_draw_counter >= 0)
            loading_draw_counter++;
        if(frontendmanager.fe_done_loading)
            highlighted->Draw();
        else loading->Draw();
    }
}
